from collections import Counter
class Solution:
    def maxRuns(self, s: str) -> int:
        cnt = Counter()
        run = 1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                run += 1
            else:
                cnt[run] += 1
                run = 1
        cnt[run] += 1
        return max(cnt.values())

