class Solution {
public:
    int maxRuns(string s) {
        unordered_map<int,int> cnt;
        int run = 1, best = 0;
        for (size_t i = 1; i <= s.size(); i++) {
            if (i < s.size() && s[i] == s[i-1]) run++;
            else { best = max(best, ++cnt[run]); run = 1; }
        }
        return best;
    }
};

c.java:
class Solution {
    public int maxRuns(String s) {
        Map<Integer,Integer> cnt = new HashMap<>();
        int run = 1, best = 0;
        for (int i = 1; i <= s.length(); i++) {
            if (i < s.length() && s.charAt(i) == s.charAt(i-1)) run++;
            else { best = Math.max(best, cnt.merge(run, 1, Integer::sum)); run = 1; }
        }
        return best;
    }
}

