var maxRuns = function(s) {
    const cnt = new Map();
    let run = 1, best = 0;
    for (let i = 1; i <= s.length; i++) {
        if (i < s.length && s[i] === s[i-1]) run++;
        else {
            cnt.set(run, (cnt.get(run) || 0) + 1);
            best = Math.max(best, cnt.get(run));
            run = 1;
        }
    }
    return best;
};
